//! A compiled program as the firmware sees it (generated by `model/rustgen.py`
//! from `model.isa.Program`).

pub const N_COEF: usize = 256;
pub const N_TAP: usize = 256;
pub const N_LFO: usize = 4;
pub const N_FADE: usize = 2;
pub const MAX_PARAMS: usize = 32;
pub const FADE_ONE: u32 = 1 << 24;
/// General-purpose registers (state, modulation, temporaries): R0..R63.
pub const REG_GENERAL: usize = 64;
/// The output registers OUT0..OUT3 (a program need not write them all).
pub const REG_OUT: usize = 68;
pub const N_OUT: usize = 4;

pub const SPACE_PSRAM: u8 = 0;
pub const SPACE_EBR: u8 = 1;
pub const TAP_READ: u8 = 0;
pub const TAP_WRITE: u8 = 1;
pub const TAP_MOD: u8 = 2;

pub struct ParamDecl {
    pub name: &'static str,
    /// The name as the menu shows it.
    pub label: &'static str,
    pub default: f64,
    pub lo: f64,
    pub hi: f64,
    pub unit: &'static str,
    /// Menu grid: `steps` + 1 values, on a log scale if `log`, else linear.
    pub log: bool,
    pub steps: u16,
    /// Grid index of the default (which reads as the default exactly).
    pub default_index: u16,
    /// Decimals to show, or -1 for "by magnitude" (log parameters).
    pub decimals: i8,
    /// Crossfade group, or -1.
    pub fade: i8,
    /// Menu page (index in `program::PAGES`) and slot on it.
    pub page: u8,
    pub slot: u8,
    /// One sentence for the menu's help line.
    pub help: &'static str,
}

impl ParamDecl {
    /// The value at menu grid index `i`.
    pub fn at(&self, i: u16) -> f64 {
        let t = i.min(self.steps) as f64 / self.steps as f64;
        if i == self.default_index {
            self.default
        } else if i >= self.steps {
            self.hi
        } else if self.log {
            self.lo * crate::math::pow(self.hi / self.lo, t)
        } else {
            self.lo + (self.hi - self.lo) * t
        }
    }

    /// The value at position `t` (0..1) of the range, on the grid's scale
    /// (log or linear): between grid points, for control voltages.
    pub fn at_t(&self, t: f64) -> f64 {
        let t = t.clamp(0.0, 1.0);
        if t >= 1.0 {
            self.hi
        } else if self.log {
            self.lo * crate::math::pow(self.hi / self.lo, t)
        } else {
            self.lo + (self.hi - self.lo) * t
        }
    }

    /// Position (0..1) of grid index `i`.
    pub fn t_of(&self, i: u16) -> f64 {
        i.min(self.steps) as f64 / self.steps as f64
    }
}

/// Which parameter values an expression is evaluated with: the current ones,
/// or those of one side of a crossfade group.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Env {
    Current,
    Side(u8, u8),
}

/// A parameter-driven table value: a coefficient (f32 of the expression), a
/// tap offset (`base - round(expression)`, a delay in samples) or an LFO
/// increment (the expression in Hz).
pub struct Expr {
    pub target: u16,
    pub base: i32,
    pub env: Env,
    /// Bit i: depends on parameter i.
    pub params: u32,
    /// The expression (`crate::expr`), over its program's `consts`.
    pub code: &'static [u8],
}

impl Expr {
    pub fn eval(&self, prog: &Program, p: &[f64]) -> f64 {
        crate::expr::eval(self.code, prog.consts, p)
    }
}

#[derive(Clone, Copy)]
pub struct TapDesc {
    pub space: u8,
    pub kind: u8,
    pub offset: u32,
    pub depth: u16,
    pub mreg: u8,
    pub buf: u16,
    pub bmask: u16,
    pub stream: i16,
    pub group: i8,
    pub side: u8,
}

/// A named starting point: (parameter index, menu grid index) pairs; the
/// other parameters take their defaults. `mods`: (modulation source, as
/// `cv::SOURCE_NAMES`; parameter index; depth in percent) for the input
/// followers. If any preset of a type has mods, each preset sets the
/// type's follower depths to exactly its own.
pub struct Preset {
    pub name: &'static str,
    pub values: &'static [(u8, u16)],
    pub mods: &'static [(u8, u8, i8)],
}

/// A one-shot envelope the firmware fires (the spring's kick): firing sets
/// register `reg` to 1.0 and the program decays it.
pub struct Trigger {
    pub name: &'static str,
    pub reg: u8,
    pub help: &'static str,
}

pub struct Program {
    pub name: &'static str,
    /// The type's name and one-sentence description, for the menu.
    pub title: &'static str,
    pub description: &'static str,
    pub fs: u32,
    pub instrs: &'static [u64],
    pub coefs: &'static [u32],
    pub regs: &'static [(u8, u32)],
    pub lfo_phase: [u32; N_LFO],
    pub lfo_inc: [u32; N_LFO],
    /// Ring sizes in words: PSRAM, block RAM.
    pub mem_words: [u32; 2],
    pub params: &'static [ParamDecl],
    pub presets: &'static [Preset],
    pub triggers: &'static [Trigger],
    pub coef_exprs: &'static [Expr],
    pub tap_exprs: &'static [Expr],
    pub lfo_exprs: &'static [Expr],
    /// The expressions' constants.
    pub consts: &'static [f64],
    /// Per crossfade group: (parameter index, fade samples).
    pub fades: &'static [(u8, u32)],
    pub taps: &'static [TapDesc],
    /// Tap index of each PSRAM stream.
    pub streams: &'static [u8],
    /// Per crossfade group: samples a changed PSRAM tap needs before it is heard.
    pub warmup: &'static [u32],
    pub burst: u32,
}
